//! Checkpoint 3, technique tests: is the library correct for the right
//! reasons?
//!
//! Run: cargo test --test technique
//!
//! These tests look at how the code works: what it allocates, what it
//! borrows, how often it calls a closure, and whether its order agrees with
//! its equality. All of them must pass, in debug and with `--release`, for
//! the "proficient" level in RUBRIC.md. Do not edit this file.

mod common;

use std::cell::Cell;
use std::cmp::Ordering;
use std::collections::BinaryHeap;
use std::mem::size_of;
use std::rc::Rc;

use common::{measure, within};
use matchday::{League, Outcome, Row, Tally};

fn tally(won: u32, drawn: u32, lost: u32, goals_for: u32, goals_against: u32) -> Tally {
    Tally {
        won,
        drawn,
        lost,
        goals_for,
        goals_against,
    }
}

/// A league of `count` teams with different records. Team `i` is called
/// `team0000`, `team0001`, ...
fn big_league(count: usize) -> League {
    let names: Vec<String> = (0..count).map(|i| format!("team{i:04}")).collect();
    let mut league = League::new(names.iter().map(String::as_str)).unwrap();
    for (i, home) in names.iter().enumerate() {
        let away = &names[(i * 7 + 1) % count];
        if home != away {
            league
                .record(home, away, ((i % 6) as u8, (i % 4) as u8))
                .unwrap();
        }
    }
    league
}

/// A league in which every team has played more than five matches.
fn warm_league() -> League {
    let teams = ["Herons", "Kestrels", "Otters", "Owls"];
    let mut league = League::new(teams).unwrap();
    for round in 0..4u8 {
        for home in teams {
            for away in teams {
                if home != away {
                    league.record(home, away, (round, 1)).unwrap();
                }
            }
        }
    }
    league
}

// -------------------------------------------------------------- allocation

#[test]
fn reading_the_league_does_not_allocate() {
    let league = warm_league();
    let name = String::from("Kestrels");
    let (seen, heap) = measure(|| {
        let known = league.tally(&name).map(Tally::played);
        let unknown = league.tally("Nobody United").is_some();
        let indexed = league[name.as_str()].goals_for;
        let teams = league.teams().map(str::len).sum::<usize>();
        let wins = league
            .form(&name)
            .map(|form| form.rev().filter(|&o| o == Outcome::Win).count());
        (known, unknown, indexed, teams, wins)
    });
    assert_eq!(seen, (Some(24), false, 30, 24, Some(3)));
    assert_eq!(
        heap.calls, 0,
        "looking up a team and reading its tally, its form or the list of names allocated {} \
         time(s). A `&str` can find a `String` key as it is, and the iterators can borrow \
         from the league.",
        heap.calls
    );
}

#[test]
fn recording_does_not_grow_the_league() {
    let mut league = warm_league();
    let home = String::from("Otters");
    let (result, heap) = measure(|| {
        for round in 0..1000u32 {
            league.record(&home, "Herons", ((round % 3) as u8, 1))?;
            league.record("Owls", &home, (0, (round % 2) as u8))?;
        }
        Ok::<(), matchday::RecordError>(())
    });
    assert_eq!(result, Ok(()));
    assert_eq!(league["Otters"].played(), 24 + 2000);
    assert_eq!(
        heap.calls, 0,
        "2000 more matches between teams with a full form allocated {} time(s). The league \
         must not keep a list of matches, the form must stay at five outcomes, and finding \
         a team must not build a String.",
        heap.calls
    );
}

#[test]
fn top_holds_only_a_few_rows() {
    let league = big_league(2000);
    let all = league.standings();
    let (best, heap) = measure(|| league.top(3));
    assert_eq!(best, all[..3]);
    assert!(
        heap.bytes <= 1024,
        "top(3) in a league of 2000 teams requested {} bytes of heap memory; the budget is \
         1024. Building and sorting the whole table needs about {} bytes. Keep only the best \
         rows seen so far.",
        heap.bytes,
        2000 * size_of::<Row<'_>>()
    );

    let (best, heap) = measure(|| league.top(0));
    assert!(best.is_empty());
    assert!(heap.bytes <= 1024, "top(0) requested {} bytes", heap.bytes);
}

#[test]
fn top_of_everything_does_not_reserve_for_k() {
    let league = big_league(50);
    let all = league.standings();
    let (best, heap) = measure(|| league.top(usize::MAX / 2));
    assert_eq!(best, all);
    assert!(
        heap.bytes <= 64 * 1024,
        "top(k) for a huge k requested {} bytes in a league of 50 teams; the result can never \
         have more rows than the league has teams",
        heap.bytes
    );
}

#[test]
fn fixtures_are_computed_one_at_a_time() {
    let count = 3000;
    let checks = within(20, "walking the fixtures of 3000 teams", move || {
        let league = big_league(count);
        let (mut fixtures, creating) = measure(|| league.fixtures());
        let (seen, reading) = measure(|| {
            let total = fixtures.len();
            let first = fixtures.next();
            let second = fixtures.next();
            let last = fixtures.next_back();
            let mut skipped = 0;
            for _ in 0..10_000 {
                skipped += usize::from(fixtures.next().is_some());
                skipped += usize::from(fixtures.next_back().is_some());
            }
            (total, first, second, last, skipped, fixtures.size_hint())
        });
        let left = count * (count - 1) - 20_003;
        assert_eq!(
            seen,
            (
                count * (count - 1),
                Some(("team0000", "team0001")),
                Some(("team0000", "team0002")),
                Some(("team2999", "team2998")),
                20_000,
                (left, Some(left)),
            )
        );
        (creating, reading)
    });
    let (creating, reading) = checks;
    assert!(
        creating.calls <= 1 && creating.bytes <= count * size_of::<&str>(),
        "fixtures() for 3000 teams allocated {} time(s) and {} bytes; the budget is one \
         allocation of {} bytes. There are almost nine million pairings: compute each one \
         when it is asked for.",
        creating.calls,
        creating.bytes,
        count * size_of::<&str>()
    );
    assert_eq!(
        reading.calls, 0,
        "next, next_back, len and size_hint of Fixtures allocated {} time(s)",
        reading.calls
    );
}

// --------------------------------------------------------------- borrowing

#[test]
fn rows_and_fixtures_borrow_the_names_of_the_league() {
    // A name that is borrowed from the league has the same address every
    // time it is handed out. A copy that is made for each call has not. The
    // test does not ask where in the league the string is kept.
    let league = warm_league();
    let row_names = |rows: Vec<Row<'_>>| -> Vec<*const u8> {
        rows.iter().map(|row| row.team.as_ptr()).collect()
    };
    assert_eq!(
        row_names(league.standings()),
        row_names(league.standings()),
        "the team of a row must be the league's own string, not a copy: two calls of \
         standings() must hand out the same strings"
    );
    assert_eq!(
        row_names(league.top(2)),
        row_names(league.top(2)),
        "the team of a row must be the league's own string, not a copy: two calls of top() \
         must hand out the same strings"
    );
    let pairing_names = || -> Vec<(*const u8, *const u8)> {
        league
            .fixtures()
            .take(100)
            .map(|(home, away)| (home.as_ptr(), away.as_ptr()))
            .collect()
    };
    assert_eq!(
        pairing_names(),
        pairing_names(),
        "the names of a pairing must be the league's own strings, not copies: two calls of \
         fixtures() must hand out the same strings"
    );
}

#[test]
fn rows_and_pairings_outlive_the_iterator_that_made_them() {
    // This compiles only because the names borrow from the league and not
    // from the `Fixtures` value or from a temporary list inside it.
    let league = warm_league();
    let first = {
        let mut fixtures = league.fixtures();
        fixtures.next().unwrap()
    };
    let leader = league.standings()[0].team;
    assert_eq!(first, ("Herons", "Kestrels"));
    assert_eq!(leader.len(), league.top(1)[0].team.len());
}

// ---------------------------------------------------------------- closures

fn counted_rule(calls: &Rc<Cell<usize>>) -> impl Fn(&Tally) -> u64 + 'static {
    let calls = Rc::clone(calls);
    move |t| {
        calls.set(calls.get() + 1);
        3 * u64::from(t.won) + u64::from(t.drawn)
    }
}

#[test]
fn standings_ask_the_rule_once_for_each_team() {
    let calls = Rc::new(Cell::new(0));
    let names: Vec<String> = (0..64).map(|i| format!("t{i:02}")).collect();
    let mut league = League::new(names.clone())
        .unwrap()
        .with_rule(counted_rule(&calls));
    for pair in names.windows(2) {
        league.record(&pair[0], &pair[1], (1, 0)).unwrap();
    }
    assert_eq!(
        calls.get(),
        0,
        "`record` does not need points; the rule runs in standings and top"
    );

    let rows = league.standings();
    assert_eq!(rows.len(), 64, "one row for each of the 64 teams");
    assert_eq!(
        calls.get(),
        64,
        "standings() called the rule {} times for 64 teams. Compute the points of a team \
         once, when its row is made. A rule that runs inside the comparison of a sort runs \
         hundreds of times.",
        calls.get()
    );
}

#[test]
fn top_asks_the_rule_once_for_each_team() {
    let calls = Rc::new(Cell::new(0));
    let names: Vec<String> = (0..64).map(|i| format!("t{i:02}")).collect();
    let league = League::new(names).unwrap().with_rule(counted_rule(&calls));
    assert_eq!(league.top(5).len(), 5, "top(5) of 64 teams has 5 rows");
    assert_eq!(
        calls.get(),
        64,
        "top(5) called the rule {} times for 64 teams; once for each team is enough",
        calls.get()
    );
}

#[test]
fn the_rule_is_dropped_with_the_league() {
    // The league owns its closures. When the league goes away, or when
    // another rule replaces the first, what they captured is released.
    let token = Rc::new(());
    let first = Rc::clone(&token);
    let second = Rc::clone(&token);
    let third = Rc::clone(&token);
    let mut league = League::new(["a", "b"])
        .unwrap()
        .with_rule(move |_| Rc::strong_count(&first) as u64);
    assert_eq!(
        Rc::strong_count(&token),
        4,
        "the test holds the token and three clones of it; one clone is inside the rule"
    );
    league = league.with_rule(move |_| Rc::strong_count(&second) as u64);
    assert_eq!(
        Rc::strong_count(&token),
        3,
        "the rule that was replaced must be dropped"
    );
    league.on_record(move |_, _, _| drop(Rc::clone(&third)));
    league.record("a", "b", (1, 1)).unwrap();
    assert_eq!(league.standings()[0].points, 3);
    drop(league);
    assert_eq!(
        Rc::strong_count(&token),
        1,
        "the league must drop its rule and its observers"
    );
}

// ------------------------------------------------------------------- order

#[test]
fn row_order_agrees_with_equality() {
    // Same team, points, goal difference and goals for; the records differ.
    let one_win = Row {
        team: "a",
        tally: tally(1, 0, 2, 4, 4),
        points: 3,
    };
    let three_draws = Row {
        team: "a",
        tally: tally(0, 3, 0, 4, 4),
        points: 3,
    };
    assert_ne!(
        one_win, three_draws,
        "rows are equal only when all three fields are equal"
    );
    assert_ne!(
        one_win.cmp(&three_draws),
        Ordering::Equal,
        "`cmp` may return Equal only for rows that are `==`. These two rows differ in their \
         tally, so the order needs one more key after the name."
    );
    assert_eq!(
        one_win.cmp(&three_draws),
        three_draws.cmp(&one_win).reverse(),
        "if a < b then b > a"
    );
    assert_eq!(
        one_win.partial_cmp(&three_draws),
        Some(one_win.cmp(&three_draws))
    );

    // A collection that relies on the order keeps both rows.
    let heap = BinaryHeap::from([one_win, three_draws, one_win]);
    let mut sorted = heap.into_sorted_vec();
    sorted.dedup();
    assert_eq!(
        sorted.len(),
        2,
        "two different rows went into the heap (one of them twice), so two must be left"
    );

    // Every pair of rows that differ in one tally field only.
    let base = tally(2, 2, 2, 2, 2);
    let variants = [
        tally(3, 2, 2, 2, 2),
        tally(2, 3, 2, 2, 2),
        tally(2, 2, 3, 2, 2),
        tally(2, 2, 2, 3, 2),
        tally(2, 2, 2, 2, 3),
    ];
    for changed in variants {
        let a = Row {
            team: "a",
            tally: base,
            points: 8,
        };
        let b = Row {
            team: "a",
            tally: changed,
            points: 8,
        };
        assert_ne!(
            a.cmp(&b),
            Ordering::Equal,
            "{base:?} and {changed:?} are different tallies"
        );
        assert_eq!(a.cmp(&b), b.cmp(&a).reverse());
    }
}

#[test]
fn row_order_is_transitive_over_many_rows() {
    // Sorting, then checking every neighbour, finds an order that
    // contradicts itself (for example one that subtracts unsigned numbers).
    let mut rows = Vec::new();
    for points in [0u64, 3, u64::MAX] {
        for goals_for in [0u32, 1, u32::MAX] {
            for goals_against in [0u32, 1, u32::MAX] {
                for team in ["a", "b"] {
                    rows.push(Row {
                        team,
                        tally: tally(1, 0, 0, goals_for, goals_against),
                        points,
                    });
                }
            }
        }
    }
    rows.sort();
    for pair in rows.windows(2) {
        let (a, b) = (&pair[0], &pair[1]);
        assert!(a < b, "after sorting, {a:?} must be smaller than {b:?}");
        assert!(a.points >= b.points);
        if a.points == b.points {
            assert!(a.tally.goal_difference() >= b.tally.goal_difference());
        }
    }
}
